import{_ as l,C as r,o as c,c as h,j as e,a as o,E as a,a5 as n}from"./chunks/framework.CyyS6Zdm.js";const P=JSON.parse('{"title":"按钮组","description":"","frontmatter":{},"headers":[],"relativePath":"components/button-group.md","filePath":"components/button-group.md","lastUpdated":1787173379000}'),s={name:"components/button-group.md"},u={id:"按钮组",tabindex:"-1"};function p(b,t,q,m,x,f){const i=r("Badge"),d=r("XhDemo");return c(),h("div",null,[e("h1",u,[t[0]||(t[0]=o("按钮组 ",-1)),a(i,{type:"info",text:"button-group"}),t[1]||(t[1]=o()),t[2]||(t[2]=e("a",{class:"header-anchor",href:"#按钮组","aria-label":'Permalink to "按钮组 <Badge type="info" text="button-group" />"'},"​",-1))]),t[3]||(t[3]=n('<p>把一组语义相关的按钮连成一条：相邻两段共用一条边，圆角只留在两端，视觉上是一个控件。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>几个动作属于同一件事，且并列关系明确（保存 / 另存为 / 导出）。</li><li>想让整组按钮的档位、形态与语气写一次就够。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>组内各段是互斥选项、要选中其中一个：那是<a href="./toggle-group">切换按钮组</a>——它有选中语义与方向键导航，按钮组两样都没有。</li><li>各按钮之间没有语义关联：单独摆开，用间距区分，别硬连成一条。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>只有 <code>root</code> 一个部件：组内每一段是作者自己的按钮，不是本组件的角色节点。</li><li>尺寸、形态、语气写在容器上，沿自定义属性流给组内每一段。</li><li>横排在左右两端留圆角，竖排改在上下两端；合边跟着换轴。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>一组相关按钮连成一条：相邻两段共用一条边，圆角只留在两端</p>',10)),a(d,{src:"button-group/01-basic"}),t[4]||(t[4]=e("h3",{id:"排布",tabindex:"-1"},[o("排布 "),e("a",{class:"header-anchor",href:"#排布","aria-label":'Permalink to "排布"'},"​")],-1)),t[5]||(t[5]=e("p",null,"横排在左右两端留圆角，竖排改在上下两端；合边跟着换轴",-1)),a(d,{src:"button-group/02-orientation"}),t[6]||(t[6]=e("h3",{id:"尺寸",tabindex:"-1"},[o("尺寸 "),e("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),t[7]||(t[7]=e("p",null,"高度、内边距与字号在组上写一次，沿自定义属性流给组内每一段",-1)),a(d,{src:"button-group/03-size"}),t[8]||(t[8]=e("h3",{id:"形态与语气",tabindex:"-1"},[o("形态与语气 "),e("a",{class:"header-anchor",href:"#形态与语气","aria-label":'Permalink to "形态与语气"'},"​")],-1)),t[9]||(t[9]=e("p",null,"形态决定颜色怎么用、语气决定用哪族颜色，两者都写在组上，段自己不重复标注",-1)),a(d,{src:"button-group/04-variant-tone"}),t[10]||(t[10]=n('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-button-group&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhButtonGroup</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/button-group.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;button-group&quot;</code>：<strong><code>root</code></strong></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>orientation</code></td><td><code>&#39;horizontal&#39; | &#39;vertical&#39;</code></td><td></td><td>排布：horizontal / vertical，决定相邻两段在哪个轴上合边。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg，落到根上供皮肤写进组内按钮的高度、内边距与字号槽位。</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，落到根上沿继承流给组内每一段。</td></tr><tr><td><code>variant</code></td><td><code>ActionVariant</code></td><td></td><td>形态：solid / subtle / outline / ghost，落到根上供皮肤写进组内按钮的颜色槽位。</td></tr></tbody></table><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>connect</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/" target="_blank" rel="noreferrer">W3C APG</a></p><p>无键盘交互（不接收焦点，或焦点行为完全由原生元素提供）。</p><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>role</code></td><td>&#39;group&#39;</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/button-group.css</code> 按部件选择：<code>[data-scope=&quot;button-group&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>root</code></td><td><code>data-variant</code></td><td>props.variant</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-button-group-radius</code></p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>组内放<a href="./button">按钮</a>；最后一段放一个带菜单的按钮即得&quot;主动作 + 更多&quot;的分裂按钮。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>一组以三到五段为宜，再多就该收进<a href="./menu">菜单</a>。</li><li>档位只写在组上，别再逐段重复——两处写法不一致时段与段会错位。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>用按钮组表达选中态：它不出 <code>aria-pressed</code>，读屏用户听不出哪一段是当前项。</li><li>组内混进不可点的说明文字，破坏&quot;每一段都是动作&quot;的预期。</li></ul>',32))])}const k=l(s,[["render",p]]);export{P as __pageData,k as default};
